from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=float)
def compute_element(alpha, x_i, y_i):
    val = alpha * x_i
    val += y_i
    return val

def main(alpha, x, y):
    if alpha == 0:
        return y

    M = len(x)
    tasks = [compute_element(alpha, x[i], y[i]) for i in range(M)]

    return compss_wait_on(tasks)
